/* eslint-disable max-lines */
import { createStyles } from '@Pimcore/modules/ant-design/styles/create-styles'
import { isEmptyValue } from '@Pimcore/utils/type-utils'
import { type SelectTheme } from './select'
import { toCssDimension } from '@sdk/utils'

interface StylesProps {
  width?: number
  theme?: SelectTheme
  skeletonWidth?: number | string
  skeletonMaxWidth?: number | string
  skeletonMinWidth?: number | string
}

const ICON_WIDTH = 16

export const useStyles = createStyles(({ css, token }, props: StylesProps) => {
  return {
    selectContainer: css`
      position: relative;
      
      &:hover {
        .custom-select-icon {
          color: ${token.colorPrimary};
        }
      }
    `,

    // WARNING state
    selectContainerWarning: css`
      &:hover {
        .custom-select-icon {
          color: ${token.colorWarningHover} !important;
        }
      }
      
      .ant-select-status-warning {
        &.ant-select-open, &.ant-select-focused {
          .ant-select-selection-item {
            color: ${token.colorText};
          }

          .ant-select-arrow {
            color: ${token.colorWarningHover} !important;
          }
        }

        &:hover {
          .ant-select-selection-item {
            color: ${token.colorText};
          }

          .ant-select-arrow {
            color: ${token.colorWarningHover} !important;
          }
        }
       }
    `,

    // ERROR state
    selectContainerError: css`
      &:hover {
        .custom-select-icon {
          color: ${token.colorErrorHover} !important;
        }
      }
      
      .ant-select-status-error {
        &.ant-select-open, &.ant-select-focused {
          .ant-select-selection-item {
            color: ${token.colorText};
          }

          .ant-select-arrow {
            color: ${token.colorErrorHover} !important;
          }
        }

        &:hover {
          .ant-select-selection-item {
            color: ${token.colorText};
          }

          .ant-select-arrow {
            color: ${token.colorErrorHover} !important;
          }
        }
      }
    `,

    selectContainerWithClear: css`
      &:hover {
        .ant-select:not(.ant-select-disabled):has(.ant-select-clear) {
          .ant-select-arrow {
            display: none;
          }
        }
      }
    `,

    selectContainerPrimary: css`
      .ant-select:not(.ant-select-disabled) {
        .ant-select-selector {
          border-color: ${token.colorPrimaryBorder};
        }

        .ant-select-selection-item {
          color: ${token.colorPrimary};
        }

        .ant-select-selection-placeholder {
          color: ${token.colorPrimary};
        }

        .ant-select-arrow {
          color: ${token.colorPrimary} !important;
        }

      }
    `,

    select: css`
      width: ${!isEmptyValue(props.width) ? `${props.width}px` : 'initial'};
      
      .ant-select-selector {
        padding: 0 ${token.controlPaddingHorizontal}px !important;
      }

      // Honor the small size's horizontal padding (matches the small Input);
      // without this the !important rule above forces the default 12px on small selects.
      &.ant-select-sm .ant-select-selector {
        padding: 0 ${token.controlPaddingHorizontalSM}px !important;
      }

      .ant-select-arrow {
        color: ${token.colorIcon} !important;
      }

      // DEFAULT select
      &.ant-select-open, &.ant-select-focused {
        .ant-select-selection-item:not(:has(.pimcore-workflow-place-indicator)) {
          color: ${token.colorPrimary};
        }

        .ant-select-arrow {
          color: ${token.colorPrimary} !important;
        }
      }

      &:hover {
        .ant-select-selection-item:not(:has(.pimcore-workflow-place-indicator)) {
          color: ${token.colorPrimary};
        }

        .ant-select-arrow {
          color: ${token.colorPrimary} !important;
        }
      }

      // MULTIPLE select
      &.ant-select-multiple {
        &.ant-select {
          .ant-select-selector {
            padding: 1px ${token.controlPaddingHorizontal}px 1px ${token.paddingXXS}px !important;
          }
        }

        // The !important padding above skews Ant Design's JS mirror width measurement,
        // causing the search input to clip typed text. flex: 1 (= flex: 1 1 0%) overrides
        // the JS-set width via flex-basis precedence and grows to fill the remaining row
        // space without wrapping to a new line (unlike flex-basis: 100%).
        .ant-select-selection-overflow-item-suffix {
          flex: 1 !important;
        }
        .ant-select-selection-search {
          width: 100% !important;
        }
        .ant-select-selection-search-input {
          width: 100% !important;
        }

        &:hover {
          .ant-select-selection-item {
            .ant-select-selection-item-content {
              color: ${token.colorText} !important;
            }
          }
        }
      }

      // DISABLED state
      &.ant-select.ant-select-disabled {
        .ant-select-selector {
          border-color: ${token.colorBorder} !important;
        }
        
        .ant-select-selection-item {
          color: ${token.colorTextDisabled};
        }

        .ant-select-arrow {
          color: ${token.colorTextDisabled} !important;
        }
        
        &.versionFieldItem {
          .ant-select-selection-item {
            color: ${token.colorText} !important;
          }
        }

        &.versionFieldItem:not(.versionFieldItemHighlight) {
          .ant-select-selector {
            border-color: transparent !important;
          }
        }

        &.versionFieldItemHighlight {
          .ant-select-selector {
            background-color: ${token.Colors.Brand.Warning.colorWarningBg} !important;
          }
        }
      }
      
      &.ant-select--inherited {
        .ant-select-selector {
        background: ${token.colorBgContainerDisabled} !important;
        color: ${token.colorTextDisabled};
        
        .ant-select-selection-item-remove .anticon {
          color: ${token.colorTextDisabled};
        }

        .ant-select-selection-item-content {
            color: ${token.colorTextDisabled} !important;
          }
        }
        
        &.ant-select-multiple {
          &:hover {
            .ant-select-selection-item {
              .ant-select-selection-item-content {
                color: ${token.colorTextDisabled} !important;
              }
            }
          }
        }
      }
    `,

    arrowIcon: css`
      pointer-events: none !important
    `,

    selectWithCustomIcon: css`
      &.ant-select {
        .ant-select-selector {
          padding: 0 ${token.controlPaddingHorizontal}px 0 ${token.controlPaddingHorizontal + ICON_WIDTH + token.marginXXS}px !important;
        }
      }
    `,

    customIcon: css`
      position: absolute;
      left: 10px;
      top: 50%;
      transform: translateY(-50%);
      z-index: 1;
      color: ${token.colorIcon};
    `,

    customIconActive: css`
       color: ${token.colorPrimary} !important;
     `,

    customIconWarning: css`
       color: ${token.colorWarningHover};
     `,

    customIconError: css`
       color: ${token.colorErrorHover};
     `,

    skeletonLoading: css`
      width: ${toCssDimension(props.skeletonWidth, '100%')};
      max-width: ${toCssDimension(props.skeletonMaxWidth, '100%')};
      min-width: ${toCssDimension(props.skeletonMinWidth, 'auto')};
      display: block;

      .ant-skeleton,
      .ant-skeleton-input {
        width: ${toCssDimension(props.skeletonWidth, '100%')} !important;
        max-width: ${toCssDimension(props.skeletonMaxWidth, '100%')} !important;
        min-width: ${toCssDimension(props.skeletonMinWidth, 'auto')} !important;
        display: block;
      }
    `,

    clearOptionWrapper: css`
      &:has(> button:first-child:hover) .ant-select-item-option-active {
        background-color: transparent !important;
      }
    `,

    clearOption: css`
      display: flex;
      align-items: center;
      gap: ${token.marginXS}px;
      width: 100%;
      min-height: ${token.controlHeight}px;
      padding: ${(token.controlHeight - token.fontSize * token.lineHeight) / 2}px ${token.controlPaddingHorizontal}px;
      font-size: ${token.fontSize}px;
      line-height: ${token.lineHeight};
      color: ${token.colorTextSecondary};
      cursor: pointer;
      border: none;
      border-radius: ${token.borderRadiusSM}px;
      background: none;
      transition: background ${token.motionDurationSlow} ease;

      &:hover {
        background-color: ${token.controlItemBgHover};
      }
    `
  }
})
